if($query!==''){$q=$pdo->prepare('SELECT id,jmeno,prijmeni,narozeni FROM sportovci WHERE jmeno LIKE ? OR prijmeni LIKE ? ORDER BY prijmeni,jmeno LIMIT 50');$q->execute(['%'.$query.'%','%'.$query.'%']);$people=$q->fetchAll(PDO::FETCH_ASSOC);}
$offers=clubProgramAdminOffers($pdo);$offer=null;foreach($offers as$o)if((int)$o['id']===$offerId)$offer=$o;
$payers=[];$papers=[];$personRow=null;if($person>0){$q=$pdo->prepare('SELECT id,jmeno,prijmeni FROM sportovci WHERE id=?');$q->execute([$person]);$personRow=$q->fetch(PDO::FETCH_ASSOC);$q=$pdo->prepare("SELECT DISTINCT a.id,a.jmeno,a.prijmeni,a.email FROM verejni_uzivatele a JOIN account_person_roles r ON r.account_id=a.id WHERE r.sportovec_id=? AND r.status='approved' AND r.relation_role IN ('self','guardian') AND a.aktivni=1 AND a.email_overeno=1 AND r.valid_from<=CURRENT_TIMESTAMP AND (r.valid_to IS NULL OR r.valid_to>CURRENT_TIMESTAMP)");$q->execute([$person]);$payers=$q->fetchAll(PDO::FETCH_ASSOC);if($offer){$q=$pdo->prepare("SELECT id,document_title,version_label,signed_on FROM club_paper_records WHERE sportovec_id=? AND scope_type='program' AND scope_id=? ORDER BY id DESC");$q->execute([$person,$offer['program_id']]);$papers=$q->fetchAll(PDO::FETCH_ASSOC);}}
$recent=$pdo->query('SELECT a.*,o.public_code,o.payment_status,s.jmeno,s.prijmeni,f.name AS offer_name FROM club_program_admissions a JOIN shop_orders o ON o.id=a.order_id JOIN sportovci s ON s.id=a.sportovec_id JOIN club_program_offers f ON f.id=a.offer_id ORDER BY a.id DESC LIMIT 30')->fetchAll(PDO::FETCH_ASSOC);
